settings.custom_css:
/* texto encima, a la izquierda de la imagen */
@media (min-width: 1025px) {
  selector > .e-con-inner { position: relative; }
  selector .ak-war-intro { position: absolute !important; top: 0; left: 0; width: 41% !important; z-index: 2; }
}
selector .elementor-widget-text-editor p { margin: 0; }
/* pestañas: imagen arriba, etapas abajo */
selector .ak-war-tabs .e-n-tabs { display: flex !important; flex-direction: column !important; }
selector .ak-war-tabs .e-n-tabs-content { order: 1; }
selector .ak-war-tabs .e-n-tabs-heading { order: 2; }
selector .ak-war-tabs .e-n-tabs-content > .e-con { padding: 0 !important; border: 0 !important; background: none !important; }
selector .ak-war-tabs .e-n-tabs-content > .e-con.e-active { animation: akWarFade .5s ease; }
@keyframes akWarFade { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
/* línea con avance dorado */
selector .ak-war-tabs .e-n-tabs-heading { display: flex !important; flex-wrap: nowrap !important; gap: 0 !important; position: relative; margin-top: 30px; counter-reset: akEtapa; }
selector .ak-war-tabs .e-n-tabs-heading::before { content: ""; position: absolute; left: 0; right: 0; top: 7px; height: 2px; background: linear-gradient(90deg, rgba(234,239,242,.55), rgba(234,239,242,.08)); }
selector .ak-war-tabs .e-n-tabs-heading::after { content: ""; position: absolute; left: 0; top: 7px; height: 2px; width: var(--ak-prog, 0%); background: #C49A45; transition: width .5s ease; }
selector .ak-war-tabs .e-n-tabs-heading:has(.e-n-tab-title:nth-child(2)[aria-selected="true"]) { --ak-prog: 25%; }
selector .ak-war-tabs .e-n-tabs-heading:has(.e-n-tab-title:nth-child(3)[aria-selected="true"]) { --ak-prog: 50%; }
selector .ak-war-tabs .e-n-tabs-heading:has(.e-n-tab-title:nth-child(4)[aria-selected="true"]) { --ak-prog: 75%; }
/* cada etapa: punto + «ETAPA N» + título */
selector .ak-war-tabs .e-n-tab-title { flex: 0 0 25% !important; width: 25% !important; display: flex !important; flex-direction: column !important; align-items: flex-start !important; justify-content: flex-start !important;
  text-align: left !important; background: none !important; border: 0 !important; border-radius: 0 !important; padding: 0 28px 0 0 !important; margin: 0 !important; cursor: pointer; counter-increment: akEtapa; position: relative; z-index: 1; }
selector .ak-war-tabs .e-n-tab-title::before { content: ""; width: 16px; height: 16px; border-radius: 50%; background: #070E21; border: 1.5px solid #C49A45; box-sizing: border-box; transition: transform .25s, background .25s; }
selector .ak-war-tabs .e-n-tab-title::after { content: "Etapa " counter(akEtapa); order: 1; margin-top: 44px; font: 300 16px/1.2 Inter, sans-serif; letter-spacing: .14em; text-transform: uppercase; color: #C49A45; }
selector .ak-war-tabs .e-n-tab-title-text { order: 2; margin-top: 22px; max-width: 250px; font: 700 27px/1.25 Montserrat, sans-serif !important; color: rgba(234,239,242,.5) !important; text-align: left !important; transition: color .25s; }
selector .ak-war-tabs .e-n-tab-title:hover .e-n-tab-title-text { color: rgba(234,239,242,.85) !important; }
selector .ak-war-tabs .e-n-tab-title:hover::before { transform: scale(1.25); }
selector .ak-war-tabs .e-n-tab-title[aria-selected="true"] .e-n-tab-title-text { color: #EAEFF2 !important; }
selector .ak-war-tabs .e-n-tab-title[aria-selected="true"]::before { background: #C49A45; animation: akWarPulse 1.8s ease-out infinite; }
@keyframes akWarPulse { 0% { box-shadow: 0 0 0 0 rgba(196,154,69,.75); } 70% { box-shadow: 0 0 0 14px rgba(196,154,69,0); } 100% { box-shadow: 0 0 0 0 rgba(196,154,69,0); } }
/* descripción de la etapa activa más clara */
selector .ak-war-descs .elementor-widget-text-editor { transition: color .25s; }
selector:has(.e-n-tab-title:nth-child(1)[aria-selected="true"]) .ak-war-descs > .elementor-element:nth-child(1),
selector:has(.e-n-tab-title:nth-child(2)[aria-selected="true"]) .ak-war-descs > .elementor-element:nth-child(2),
selector:has(.e-n-tab-title:nth-child(3)[aria-selected="true"]) .ak-war-descs > .elementor-element:nth-child(3),
selector:has(.e-n-tab-title:nth-child(4)[aria-selected="true"]) .ak-war-descs > .elementor-element:nth-child(4) { color: #C9CFD8 !important; }
/* cada dispositivo ve solo su versión (CSS en vez de «Ocultar en…», así el editor no la pinta gris) */
/* móvil: línea vertical con las 4 etapas e imagen numerada a todo el ancho */
selector .ak-war-mtl { position: relative; }
selector .ak-war-mtl::before { content: ""; position: absolute; left: 6px; top: 10px; bottom: 24px; width: 2px; background: linear-gradient(180deg, #C49A45, rgba(196,154,69,.25)); }
selector .ak-war-mst { position: relative; }
selector .ak-war-mst::before { content: ""; position: absolute; left: -34px; top: 2px; width: 14px; height: 14px; border-radius: 50%; background: #070E21; border: 2px solid #C49A45; box-sizing: border-box; z-index: 1; }
selector .ak-war-mst:first-child::before { background: #C49A45; }
selector .ak-war-mimg { margin-left: -16px !important; margin-right: -16px !important; width: calc(100% + 32px) !important; max-width: none !important; }
@media (max-width: 1366px) {
  selector .ak-war-tabs .e-n-tabs-heading { margin-top: 26px; }
  selector .ak-war-tabs .e-n-tab-title { padding-right: 22px !important; }
  selector .ak-war-tabs .e-n-tab-title::after { margin-top: 34px; font-size: 14px; }
  selector .ak-war-tabs .e-n-tab-title-text { margin-top: 18px; max-width: 210px; font-size: 22px !important; }
}
@media (max-width: 767px) {
  /* móvil: las 4 etapas en línea vertical arriba (se tocan), la imagen de la etapa debajo y su descripción al final */
  selector .ak-war-tabs .e-n-tabs-heading { order: 1; flex-direction: column !important; margin-top: 28px; }
  selector .ak-war-tabs .e-n-tabs-content { order: 2; margin-top: 6px; }
  selector .ak-war-tabs .e-n-tabs-heading::before { left: 7px; right: auto; top: 8px; bottom: 25%; width: 2px; height: auto; background: linear-gradient(180deg, rgba(234,239,242,.55), rgba(234,239,242,.08)); }
  selector .ak-war-tabs .e-n-tabs-heading::after { left: 7px; top: 8px; width: 2px; height: var(--ak-prog, 0%); transition: height .5s ease; }
  selector .ak-war-tabs .e-n-tab-title { flex: none !important; width: 100% !important; padding: 0 0 22px 34px !important; }
  selector .ak-war-tabs .e-n-tab-title::before { position: absolute; left: 0; top: 0; }
  selector .ak-war-tabs .e-n-tab-title::after { margin-top: 0; font-size: 12px; letter-spacing: .12em; }
  selector .ak-war-tabs .e-n-tab-title-text { margin-top: 8px; max-width: none; font-size: 17px !important; }
  /* como el XD móvil: cada etapa con su título y su texto, todos visibles */
  selector .ak-war-descs { display: none !important; }
  selector .ak-war-tabs .e-n-tab-title-text { display: block !important; width: 100%; text-align: left !important; }
  selector .ak-war-tabs .e-n-tab-title-text::after { display: block; width: 100%; margin-top: 6px; font: 400 13px/1.55 Inter, sans-serif; color: #838994; letter-spacing: 0; }
  selector .ak-war-tabs .e-n-tab-title:nth-child(1) .e-n-tab-title-text::after { content: "Integra un equipo con funciones reales de una campaña electoral."; }
  selector .ak-war-tabs .e-n-tab-title:nth-child(2) .e-n-tab-title-text::after { content: "Analiza territorio, públicos, mensaje, escenarios y plan de acción."; }
  selector .ak-war-tabs .e-n-tab-title:nth-child(3) .e-n-tab-title-text::after { content: "Enfrenta cambios de escenario, crisis, ataques, riesgos y decisiones estratégicas."; }
  selector .ak-war-tabs .e-n-tab-title:nth-child(4) .e-n-tab-title-text::after { content: "Presenta la estrategia integral de tu comando ante un jurado especializado."; }
}
